import copy
import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from gridwork.analysis import steps_to_exit


def oracle(a, b, c):
    frontier, seen, steps = [b], {b}, 0
    while frontier:
        if c in frontier:
            return steps
        nxt = []
        for r, col in frontier:
            for nr, nc in ((r + 1, col), (r - 1, col), (r, col + 1), (r, col - 1)):
                if 0 <= nr < len(a) and 0 <= nc < len(a[0]) and a[nr][nc] != "#" and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    nxt.append((nr, nc))
        frontier = nxt
        steps += 1
    return -1


def _grid(rng, rows, cols, walls):
    cells = [["."] * cols for _ in range(rows)]
    for _ in range(walls):
        r, c = rng.randrange(rows), rng.randrange(cols)
        if (r, c) not in ((0, 0), (rows - 1, cols - 1)):
            cells[r][c] = "#"
    return ["".join(row) for row in cells]


def small_args(rng):
    rows, cols = rng.randint(2, 4), rng.randint(2, 4)
    return (_grid(rng, rows, cols, rng.randint(0, 6)), (0, 0), (rows - 1, cols - 1))


def big_args(rng, n):
    return (_grid(rng, n, n, n - 1), (0, 0), (n - 1, n - 1))


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2000)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(steps_to_exit(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_inputs_are_not_modified(self):
        rng = random.Random(2001)
        for _ in range(40):
            args = small_args(rng)
            before = copy.deepcopy(args)
            steps_to_exit(*args)
            self.assertEqual(args, before)

