def oracle(a, b, c):
    parent = list(range(a))
    size = [1] * a

    def root(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    result = [None] * len(c)
    progress = 0
    for idx in sorted(range(len(c)), key=lambda k: (c[k][2], k)):
