def joined_at_step(nodes, pipes, questions):
    """Whether two junctions of the water network were connected after a given number of pipes was laid."""
    parent = list(range(nodes))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    order = sorted(range(len(questions)), key=lambda i: questions[i][2])
    answers = [False] * len(questions)
    added = 0
    for i in order:
        x, y, upto = questions[i]
        while added < upto:
            u, v = pipes[added]
            parent[find(u)] = find(v)
            added += 1
        answers[i] = find(x) == find(y)
    return answers


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

