def joined_at_step(nodes, pipes, questions):
    """Whether two junctions of the water network were connected after a given number of pipes was laid."""
    answers = []
    for x, y, upto in questions:
        adj = {}
        for u, v in pipes[:upto]:
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, []).append(u)
        seen = {x}
        stack = [x]
        while stack:
            cur = stack.pop()
            for nxt in adj.get(cur, ()):
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        answers.append(y in seen)
    return answers


