def payable_exactly(parts, total):
    """Whether the invoice total can be paid with a subset of the received payments."""
    reachable = {0}
    for x in parts:
        reachable |= {s + x for s in reachable if s + x <= total}
    return total in reachable


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

