def payable_exactly(parts, total):
    """Whether the invoice total can be paid with a subset of the received payments."""

    def go(i, left):
        if left == 0:
            return True
        if i == len(parts) or left < 0:
            return False
        return go(i + 1, left - parts[i]) or go(i + 1, left)

    return go(0, total)


