"""sched: calculations used by the nightly batch jobs."""


def longest_exact_run(flows, wanted):
    """Longest block of consecutive cash flows summing to exactly the wanted amount."""
    first = {0: -1}
    total = best = 0
    for i, v in enumerate(flows):
        total += v
        if total - wanted in first:
            best = max(best, i - first[total - wanted])
        first.setdefault(total, i)
    return best


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

