def longest_exact_run(flows, wanted):
    """Longest block of consecutive cash flows summing to exactly the wanted amount."""
    best = 0
    for start in range(len(flows)):
        total = 0
        for end in range(start, len(flows)):
            total += flows[end]
            if total == wanted:
                best = max(best, end - start + 1)
    return best


