import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from sched.analysis import latency_map


def oracle(a, b):
    import heapq
    best = {}
    queue = [(0, b)]
    while queue:
        cost, node = heapq.heappop(queue)
        if node in best:
            continue
        best[node] = cost
        for nbr, w in a.get(node, ()):
            if nbr not in best:
                heapq.heappush(queue, (cost + w, nbr))
    return best


def small_args(rng):
    size = rng.randint(1, 9)
    graph = {}
    for node in range(size):
        if rng.random() < 0.85:
            graph[node] = [(rng.randrange(size), rng.randint(1, 9)) for _ in range(rng.randint(0, 3))]
    return (graph, rng.randrange(size))


def big_args(rng, n):
    graph = {}
    for node in range(n):
        out = [((node + 1) % n, rng.randint(1, 20))]
        for _ in range(3):
            out.append((rng.randrange(n), rng.randint(1, 20)))
        graph[node] = out
    return (graph, 0)


