"""sched: calculations used by the nightly batch jobs."""


def latency_map(network, source):
    """Smallest total latency from the source to every host that is reachable."""
    dist = {source: 0}
    done = set()
    while True:
        node = None
        for cand, d in dist.items():
            if cand not in done and (node is None or d < dist[node]):
                node = cand
        if node is None:
            break
        done.add(node)
        for nbr, w in network.get(node, ()):
            nd = dist[node] + w
            if nd < dist.get(nbr, float("inf")):
                dist[nbr] = nd
    return dist


