"""datajobs: calculations used by the nightly batch jobs."""


def out_of_order_pairs(scores):
    """How many pairs of results are reversed compared with ascending order."""

    def sort(items):
        if len(items) < 2:
            return items, 0
        mid = len(items) // 2
        left, left_count = sort(items[:mid])
        right, right_count = sort(items[mid:])
        merged, i, j, cross = [], 0, 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                cross += len(left) - i
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged, left_count + right_count + cross

    return sort(list(scores))[1]


