import importlib
import os
import random
import unittest

from linemeter import BudgetExceeded, LineMeter
from opsmath.queries import best_booking_value


def oracle(a):
    jobs = sorted(a, key=lambda job: (job[1], job[0], job[2]))
    best = [0] * (len(jobs) + 1)
    for k, (s, e, p) in enumerate(jobs, 1):
        compatible = max((best[m] for m in range(k) if m == 0 or jobs[m - 1][1] <= s), default=0)
        best[k] = max(best[k - 1], compatible + p)
    return best[-1]


def small_args(rng):
    jobs = []
    for _ in range(rng.randint(0, 9)):
        s = rng.randint(0, 15)
        jobs.append((s, s + rng.randint(1, 6), rng.randint(1, 9)))
    return (jobs,)


def big_args(rng, n):
    jobs = []
    for _ in range(n):
        s = rng.randint(0, 2 * n)
        jobs.append((s, s + rng.randint(2, 14), rng.randint(1, 50)))
    return (jobs,)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(2008)
        for _ in range(150):
            args = small_args(rng)
            self.assertEqual(best_booking_value(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

