def ways_to_change(total, denoms):
    """Number of ways to make change for the total."""
    ways = [1] + [0] * total
    for coin in denoms:
        for value in range(coin, total + 1):
            ways[value] += ways[value - coin]
    return ways[total]


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

