def ways_to_change(total, denoms):
    """Number of ways to make change for the total."""

    def go(i, left):
        if left == 0:
            return 1
        if i == len(denoms) or left < 0:
            return 0
        return go(i, left - denoms[i]) + go(i + 1, left)

    return go(0, total)


