"""batchcalc: calculations used by the nightly batch jobs."""


def release_stages(depends_on):
    """Work out which services can be deployed together, stage by stage."""
    waiting = {t: len(ps) for t, ps in depends_on.items()}
    children = {}
    for t, ps in depends_on.items():
        for p in ps:
            children.setdefault(p, []).append(t)
    wave = sorted(t for t, c in waiting.items() if c == 0)
    waves = []
    while wave:
        waves.append(wave)
        nxt = []
        for t in wave:
            for c in children.get(t, ()):
                waiting[c] -= 1
                if waiting[c] == 0:
                    nxt.append(c)
        wave = sorted(nxt)
    return waves


