def max_distinct_streak(tags):
    """Longest streak of consecutive tags that are all different."""
    last = {}
    start = best = 0
    for i, item in enumerate(tags):
        if item in last and last[item] >= start:
            start = last[item] + 1
        last[item] = i
        best = max(best, i - start + 1)
    return best


