def next_higher(prices):
    """For each day, the next day on which the price is strictly higher."""
    out = [-1] * len(prices)
    pending = []
    for i, x in enumerate(prices):
        while pending and prices[pending[-1]] < x:
            out[pending.pop()] = i
        pending.append(i)
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

