def next_higher(prices):
    """For each day, the next day on which the price is strictly higher."""
    out = []
    for i in range(len(prices)):
        found = -1
        for j in range(i + 1, len(prices)):
            if prices[j] > prices[i]:
                found = j
                break
        out.append(found)
    return out


