"""ledgerlab: calculations used by the nightly batch jobs."""


def count_disorder(ranks):
    """How far a ranking is from sorted: the number of pairs that appear in the wrong relative order."""

    def sort(items):
        if len(items) < 2:
            return items, 0
        mid = len(items) // 2
        left, left_count = sort(items[:mid])
        right, right_count = sort(items[mid:])
        merged, i, j, cross = [], 0, 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                cross += len(left) - i
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged, left_count + right_count + cross

