"""batchcalc: calculations used by the nightly batch jobs."""
import bisect


def best_streak_of_records(scores):
    """How many successive personal bests are possible in this score history."""
    tails = []
    for x in scores:
        k = bisect.bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x
    return len(tails)


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

